[CmdletBinding()]
param(
  [Parameter(Mandatory)][string]$RootPath,
  [Parameter(Mandatory)][string]$HelperSha256,
  [Parameter(Mandatory)][string]$WrapperSha256,
  [Parameter(Mandatory)][string]$OutputPath
)
$ErrorActionPreference='Stop'
function Require([bool]$Condition,[string]$Message){if(-not $Condition){throw $Message}}
function Bounded-Item([string]$Path,[string]$Label){$item=Get-Item -LiteralPath $Path -Force -ErrorAction Stop;Require (-not $item.PSIsContainer) "$Label is directory";Require (($item.Attributes -band [IO.FileAttributes]::ReparsePoint)-eq 0) "$Label is reparse";Require ($item.Length -le 2097152) "$Label exceeds 2 MiB";return $item}
function Hash-Bounded([string]$Path,[string]$Label){$item=Bounded-Item $Path $Label;return (Get-FileHash -LiteralPath $item.FullName -Algorithm SHA256).Hash.ToLowerInvariant()}
function Write-Fresh([string]$Path,[string]$Text){Require (-not(Test-Path -LiteralPath $Path)) "fresh path already exists: $Path";$parent=Split-Path -Parent ([IO.Path]::GetFullPath($Path));if(-not(Test-Path -LiteralPath $parent)){[IO.Directory]::CreateDirectory($parent)|Out-Null};[IO.File]::WriteAllText($Path,$Text,(New-Object Text.UTF8Encoding($false)))}
function Read-Receipt([string]$Path){$item=Bounded-Item $Path 'transport receipt';return ([IO.File]::ReadAllText($item.FullName,(New-Object Text.UTF8Encoding($false)))|ConvertFrom-Json)}
function Quote-Arg([string]$Value){if($Value -notmatch '[\s"]'){return $Value};return '"'+$Value.Replace('"','\"')+'"'}
function Start-Transport([string]$Wrapper,[string]$Helper,[string]$HelperSha,[string]$Fixture,[string]$FixtureSha,[string]$Output,[int]$DeadlineSeconds,[string[]]$ScriptArguments=@()){
  $args=@('-NoProfile','-ExecutionPolicy','Bypass','-File',$Wrapper,'-HelperPath',$Helper,'-HelperSha256',$HelperSha,'-ScriptPath',$Fixture,'-ScriptSha256',$FixtureSha,'-OutputPath',$Output,'-DeadlineSeconds',[string]$DeadlineSeconds);if($ScriptArguments.Count -gt 0){$args+=('-ScriptArguments');$args+=@($ScriptArguments)}
  $psi=New-Object Diagnostics.ProcessStartInfo;$psi.FileName=Join-Path $PSHOME 'powershell.exe';$psi.Arguments=(($args|ForEach-Object{Quote-Arg ([string]$_)}) -join ' ');$psi.WorkingDirectory=(Split-Path -Parent $Wrapper);$psi.UseShellExecute=$false;$psi.CreateNoWindow=$true
  $process=[Diagnostics.Process]::Start($psi);Require ($null -ne $process) 'transport process did not start';try{$handle=$process.Handle;Require ($handle -ne [IntPtr]::Zero) 'transport original handle missing';$watch=[Diagnostics.Stopwatch]::StartNew();while(-not $process.HasExited -and $watch.ElapsedMilliseconds -lt 60000){Start-Sleep -Milliseconds 100};Require $process.HasExited 'transport control deadline expired';[void]$process.WaitForExit(5000);$exit=$process.ExitCode;return $exit}finally{if($process -and -not $process.HasExited){try{[void]$process.Kill();[void]$process.WaitForExit(5000)}catch{}};if($process){$process.Dispose()}}
}
function Check-PassedReceipt([object]$Receipt){Require ($Receipt.status -eq 'passed') 'positive transport receipt not passed';Require ([int64]$Receipt.childPid -gt 0) 'positive child PID missing';Require ([bool]$Receipt.childHandleAcquired) 'positive child handle missing';Require ([bool]$Receipt.childTerminal) 'positive child terminal missing';Require ([bool]$Receipt.childExitIdentity) 'positive child exit identity missing';Require ([int64]$Receipt.childExit -eq 0) 'positive child exit nonzero';Require ([int64]$Receipt.activeAfter -eq 1 -and [bool]$Receipt.selfOnly) 'positive final self-only proof missing';Require ([int64]$Receipt.peakAfterBytes -le 268435456) 'positive peak exceeds cap';Require ([string]$Receipt.failure -eq '') 'positive receipt has failure'}
function Check-HeldNoChild([object]$Receipt,[string]$Label){Require ($Receipt.status -eq 'held') "$Label status not held";Require ($null -eq $Receipt.childPid) "$Label launched child";Require ([bool]$Receipt.childHandleAcquired -eq $false) "$Label acquired child handle"}
$root=[IO.Path]::GetFullPath($RootPath);Require ($HelperSha256 -match '^[0-9a-fA-F]{64}$') 'helper control SHA-256 invalid';Require ($WrapperSha256 -match '^[0-9a-fA-F]{64}$') 'wrapper control SHA-256 invalid';$helper=Join-Path $root 'Sr0RootTransportJobV1.cs';$wrapper=Join-Path $root 'run-root-transport-job-v1.ps1';$helperSha=Hash-Bounded $helper 'helper';$wrapperSha=Hash-Bounded $wrapper 'wrapper';Require ($helperSha -ceq $HelperSha256.ToLowerInvariant()) 'helper control SHA-256 mismatch';Require ($wrapperSha -ceq $WrapperSha256.ToLowerInvariant()) 'wrapper control SHA-256 mismatch';$nonce=[guid]::NewGuid().ToString('N');$fixtureRoot=Join-Path $root ("runtime-fixtures-"+$nonce);[IO.Directory]::CreateDirectory($fixtureRoot)|Out-Null;$positive=Join-Path $fixtureRoot 'positive.ps1';$timeout=Join-Path $fixtureRoot 'timeout-descendant.ps1';$marker=Join-Path $fixtureRoot 'descendant-started.marker';$positiveText="`$ErrorActionPreference='Stop'`r`nexit 0`r`n";$timeoutText=@"
`$ErrorActionPreference='Stop'
`$psi=New-Object Diagnostics.ProcessStartInfo
`$psi.FileName=Join-Path `$PSHOME 'powershell.exe'
`$psi.Arguments='-NoProfile -ExecutionPolicy Bypass -Command "Start-Sleep -Seconds 30"'
`$psi.UseShellExecute=`$false
`$descendant=[Diagnostics.Process]::Start(`$psi)
if(`$null -eq `$descendant){exit 31}
if(`$args.Count -lt 1){exit 32}
[IO.File]::WriteAllText(`$args[0],'descendant-started')
Start-Sleep -Seconds 30
"@;Write-Fresh $positive $positiveText;Write-Fresh $timeout $timeoutText;$positiveSha=Hash-Bounded $positive 'positive fixture';$timeoutSha=Hash-Bounded $timeout 'timeout fixture';$outRoot=Join-Path $fixtureRoot 'receipts';[IO.Directory]::CreateDirectory($outRoot)|Out-Null;$status='passed';$failure=$null;$checks=New-Object System.Collections.Generic.List[string];$sentinel=$null
try {
  $positiveOut=Join-Path $outRoot 'positive.json';$positiveExit=Start-Transport $wrapper $helper $helperSha $positive $positiveSha $positiveOut 10;Require ($positiveExit -eq 0) 'positive transport exit nonzero';$positiveReceipt=Read-Receipt $positiveOut;Check-PassedReceipt $positiveReceipt;$checks.Add('positive-exit0-self-only')|Out-Null
  $sentinelPsi=New-Object Diagnostics.ProcessStartInfo;$sentinelPsi.FileName=Join-Path $PSHOME 'powershell.exe';$sentinelPsi.Arguments='-NoProfile -Command "Start-Sleep -Seconds 60"';$sentinelPsi.UseShellExecute=$false;$sentinel=[Diagnostics.Process]::Start($sentinelPsi);Require ($null -ne $sentinel) 'foreign sentinel did not start';$sentinelHandle=$sentinel.Handle;Require ($sentinelHandle -ne [IntPtr]::Zero) 'foreign sentinel handle missing'
  $timeoutOut=Join-Path $outRoot 'timeout.json';$timeoutExit=Start-Transport $wrapper $helper $helperSha $timeout $timeoutSha $timeoutOut 5 @($marker);Require ($timeoutExit -ne 0) 'timeout transport unexpectedly passed';Require (Test-Path -LiteralPath $marker) 'timeout fixture did not start descendant before deadline';$timeoutReceipt=Read-Receipt $timeoutOut;Require ($timeoutReceipt.status -eq 'held' -and [bool]$timeoutReceipt.timedOut) 'timeout receipt missing held timeout';Require ([bool]$timeoutReceipt.cleanupAttempted -and [bool]$timeoutReceipt.cleanupSelfOnly) 'timeout cleanup self-only proof missing';Require ([int64]$timeoutReceipt.cleanupTerminated -ge 2) 'timeout did not terminate child and descendant';Require ([int64]$timeoutReceipt.activeAfter -eq 1 -and [bool]$timeoutReceipt.selfOnly) 'timeout final self-only proof missing';Require (-not $sentinel.HasExited) 'foreign sentinel was terminated';$checks.Add('timeout-descendant-foreign-survival')|Out-Null
  $wrongHelperOut=Join-Path $outRoot 'wrong-helper-hash.json';$wrongHelperExit=Start-Transport $wrapper $helper ('0'*64) $positive $positiveSha $wrongHelperOut 10;Require ($wrongHelperExit -ne 0) 'wrong helper hash unexpectedly passed';$wrongHelperReceipt=Read-Receipt $wrongHelperOut;Check-HeldNoChild $wrongHelperReceipt 'wrong helper hash';Require ([string]$wrongHelperReceipt.failure -match 'helper SHA-256 mismatch') 'wrong helper hash reason missing';$checks.Add('wrong-helper-hash-nochild')|Out-Null
  $wrongScriptOut=Join-Path $outRoot 'wrong-script-hash.json';$wrongScriptExit=Start-Transport $wrapper $helper $helperSha $positive ('0'*64) $wrongScriptOut 10;Require ($wrongScriptExit -ne 0) 'wrong script hash unexpectedly passed';$wrongScriptReceipt=Read-Receipt $wrongScriptOut;Check-HeldNoChild $wrongScriptReceipt 'wrong script hash';Require ([string]$wrongScriptReceipt.failure -match 'script SHA-256 mismatch') 'wrong script hash reason missing';Require ([int64]$wrongScriptReceipt.activeAfter -eq 1 -and [bool]$wrongScriptReceipt.selfOnly) 'wrong script hash final self-only proof missing';$checks.Add('wrong-script-hash-nochild')|Out-Null
} catch {$status='failed';$failure=([string]$_.Exception.Message);if($failure.Length -gt 1024){$failure=$failure.Substring(0,1024)}} finally {if($sentinel){try{if(-not $sentinel.HasExited){[void]$sentinel.Kill();[void]$sentinel.WaitForExit(5000)}}catch{};try{$sentinel.Dispose()}catch{}}}
$receipt=[ordered]@{kind='sr0-root-transport-runtime-controls-v1';status=$status;checks=$checks;helperSha256=$HelperSha256.ToLowerInvariant();wrapperSha256=$WrapperSha256.ToLowerInvariant();budgetBytes=268435456;limitFlags=512;foreignSentinelScoped=$true;boundedReceiptBytes=2097152;failure=$failure};if(Test-Path -LiteralPath $OutputPath){throw "runtime controls output must be fresh: $OutputPath"};$parent=Split-Path -Parent ([IO.Path]::GetFullPath($OutputPath));if(-not(Test-Path -LiteralPath $parent)){[IO.Directory]::CreateDirectory($parent)|Out-Null};$tmp="$OutputPath.$PID.$([guid]::NewGuid().ToString('N')).tmp";[IO.File]::WriteAllText($tmp,(($receipt|ConvertTo-Json -Depth 8)+"`r`n"),(New-Object Text.UTF8Encoding($false)));[IO.File]::Move($tmp,$OutputPath);if($status -ne 'passed'){exit 1}else{exit 0}
